<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; admin_required();
require __DIR__ . '/catalog_manage_view.php';
exit;
$connection=db();
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $name=trim((string)($_POST['name']??'')); $sku=trim((string)($_POST['sku']??'')); $categoryId=filter_input(INPUT_POST,'category_id',FILTER_VALIDATE_INT); $description=trim((string)($_POST['short_description']??'')); $price=filter_input(INPUT_POST,'price',FILTER_VALIDATE_FLOAT); $stock=filter_input(INPUT_POST,'stock_quantity',FILTER_VALIDATE_INT); $featured=isset($_POST['featured'])?1:0; if($name!==''&&$sku!==''&&$categoryId&&$description!==''&&$price!==false&&$stock!==false){$statement=$connection->prepare("INSERT INTO products (category_id,name,sku,short_description,price,stock_quantity,featured) VALUES (?,?,?,?,?,?,?)");$statement->bind_param('isssdii',$categoryId,$name,$sku,$description,$price,$stock,$featured);$statement->execute();flash('success','Product added to the catalog.');}else{flash('error','Please complete every product field.');}header('Location: catalog.php');exit; }
$categories=$connection->query('SELECT * FROM categories ORDER BY name')->fetch_all(MYSQLI_ASSOC);$products=$connection->query('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC')->fetch_all(MYSQLI_ASSOC);$success=flash('success');$error=flash('error');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sammy Tech | Catalog</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="../assets/css/admin.css"></head><body><div class="admin-layout"><aside><a class="admin-brand" href="index.php"><span>ST</span> SAMMY TECH</a><p class="aside-label">Operations</p><a href="index.php">Overview</a><a class="side-active" href="catalog.php">Catalog</a><a href="../index.php" target="_blank">View storefront ↗</a><a class="logout" href="logout.php">Sign out</a></aside><main class="admin-main"><header><div><p class="eyebrow">Inventory</p><h1>Catalog control.</h1></div></header><div class="catalog-layout"><section class="panel add-product"><h2>Add a product</h2><?php if($success): ?><p class="notice success"><?= e($success) ?></p><?php endif; ?><?php if($error): ?><p class="notice error"><?= e($error) ?></p><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Product name<input name="name" required></label><div class="two"><label>SKU<input name="sku" required placeholder="ST-XX-001"></label><label>Category<select name="category_id" required><?php foreach($categories as $category): ?><option value="<?= e((string)$category['id']) ?>"><?= e($category['name']) ?></option><?php endforeach; ?></select></label></div><label>Short description<textarea name="short_description" required rows="3"></textarea></label><div class="two"><label>Price (SSP)<input name="price" type="number" min="0" required></label><label>Quantity<input name="stock_quantity" type="number" min="0" required></label></div><label class="checkbox"><input type="checkbox" name="featured"> Feature on storefront</label><button type="submit">Add product →</button></form></section><section class="panel"><div class="panel-title"><h2>All products</h2><span><?= count($products) ?> items</span></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>State</th></tr></thead><tbody><?php foreach($products as $product): ?><tr><td><b><?= e($product['name']) ?></b><small><?= e($product['sku']) ?></small></td><td><?= e($product['category_name']) ?></td><td><?= money((float)$product['price']) ?></td><td><?= e((string)$product['stock_quantity']) ?></td><td><span class="status status-<?= e($product['status']) ?>"><?= e($product['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section></div></main></div></body></html>
